function App() {
  const [pct, setPct] = useState(40);
  const barStyle = {
    width: pct + '%',
    height: 20,
    background: '#2563eb',
    borderRadius: 4,
    transition: 'width 0.2s'
  };
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <div style={{ background: '#e5e7eb', borderRadius: 4 }}>
        <div style={barStyle} />
      </div>
      <p>{pct}% complete</p>
      <button onClick={() => setPct((p) => Math.min(100, p + 10))}>+10%</button>
      <button onClick={() => setPct(0)} style={{ marginLeft: 8 }}>reset</button>
    </div>
  );
}

